import sys, json
class Solution:
    def solveEquation(self, equation: str) -> str:
        coef = const = 0; side = 1; i = 0
        while i < len(equation):
            if equation[i] == '=': side = -1; i += 1; continue
            sign = 1
            if equation[i] == '+': i += 1
            elif equation[i] == '-': sign = -1; i += 1
            j = i
            while i < len(equation) and equation[i].isdigit(): i += 1
            num = equation[j:i]
            if i < len(equation) and equation[i] == 'x':
                coef += side * sign * (int(num) if num else 1); i += 1
            else: const += side * sign * int(num)
        if coef == 0: return 'Infinite solutions' if const == 0 else 'No solution'
        return 'x=' + str(-const // coef)

